-- 218 fiches minéraux supplémentaires, toutes avec photo libre : éléments, sulfures, halogénures, oxydes, carbonates, sulfates, phosphates, borates, silicates et quelques minéraloïdes.
-- Une fiche déjà présente (même nom ou même slug) n'est pas modifiée.
on conflict do nothing;

-- Cléiophane : fiche existante créée avec son seul nom ; seuls les champs vides sont complétés.
update public.minerals set
  formula = coalesce(formula, 'ZnS'),
  crystal_system = coalesce(crystal_system, 'Cubique'),
  chemical_class = coalesce(chemical_class, 'Sulfures et sulfosels'),
  hardness = coalesce(hardness, 3.5),
  hardness_max = coalesce(hardness_max, 4),
  density = coalesce(density, 3.9),
  density_max = coalesce(density_max, 4.1),
  colors = coalesce(colors, array['jaune pâle','incolore','vert pâle']::text[]),
  luster = coalesce(luster, 'adamantin'),
  cleavage = coalesce(cleavage, 'parfait (dodécaédrique)'),
  streak = coalesce(streak, 'blanc'),
  transparency = coalesce(transparency, 'transparent'),
  fracture = coalesce(fracture, 'conchoïdale'),
  fluorescence = coalesce(fluorescence, 'Parfois orangée aux UV (traces de manganèse).'),
  habit = coalesce(habit, 'Cristaux limpides tétraédriques, masses clivables.'),
  formation = coalesce(formation, 'Filons de zinc pauvres en fer et pegmatites (Franklin, Picos de Europa, Alpes).'),
  etymology = coalesce(etymology, 'Du grec kleiô (je ferme) et phainesthai (paraître) : il paraît cacher sa clarté, à cause de sa limpidité trompeuse.'),
  varieties = coalesce(varieties, 'Variété presque pure de sphalérite, quasi incolore (jusqu''à 0,1 % de fer).'),
  confusions = coalesce(confusions, 'Diamant : plus dur. Zircon : plus dense et plus dur. Quartz : sans clivage.'),
  description = coalesce(description, 'Sphalérite presque incolore, pauvre en fer, d''une limpidité rare ; taillée, elle égale le diamant par son éclat mais reste très tendre.')
where slug = 'cleiophane';
